public class TimelineService {
    private final RedisTemplate<String, String> redisTemplate;
    private static final String TIMELINE_KEY_PREFIX = "timeline:";

    public TimelineService(RedisTemplate<String, String> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    public void publishPostToFollowers(String postId, long timestamp, List<String> followerIds) {
        double score = (double) timestamp;
        for (String followerId : followerIds) {
            String key = TIMELINE_KEY_PREFIX + followerId;
            redisTemplate.opsForZSet().add(key, postId, score);
            // Trim timeline to maintain memory bounds (keep last 800 items)
            redisTemplate.opsForZSet().removeRange(key, 0, -801);
        }
    }

    public Set<String> getTimeline(String userId, int limit) {
        String key = TIMELINE_KEY_PREFIX + userId;
        // Fetch latest posts in reverse chronological order
        return redisTemplate.opsForZSet().reverseRange(key, 0, limit - 1);
    }
}
